<?php namespace App\Console\Commands;
use App\Models\{Article,Page,EditorialCategory,EditorialTag,ContentMedia};use App\Services\{LegacyContentReader,ContentTransformer,ContentSanitizer};use Illuminate\Console\Command;use Illuminate\Support\Facades\{DB,File};use Illuminate\Support\Str;
class LegacyMigrateContentCommand extends Command {protected $signature='legacy:migrate-content {--type= : post or page} {--ids= : comma-separated reviewed IDs} {--dry-run} {--apply} {--out=docs/generated/content-migration-sample}';public function handle():int{$type=$this->option('type');$ids=array_filter(array_map('intval',explode(',',(string)$this->option('ids'))));if(!in_array($type,['post','page'],true)||$ids===[]||count($ids)>5||($this->option('dry-run')&&$this->option('apply'))){$this->error('Use --type=post|page, 1-5 --ids, and at most one of --dry-run/--apply.');return 1;}$r=app(LegacyContentReader::class);$t=app(ContentTransformer::class);$s=app(ContentSanitizer::class);$report=['mode'=>$this->option('apply')?'apply':'dry-run','type'=>$type,'ids'=>$ids,'items'=>[]];foreach($ids as $id){$x=$r->read($type,$id);$v=$t->transform($x['post']->post_content);$z=$s->sanitize($v['html']);$p=$x['post'];$seo=['title'=>$x['meta']['_yoast_wpseo_title']??null,'description'=>$x['meta']['_yoast_wpseo_metadesc']??null,'canonical'=>$x['meta']['_yoast_wpseo_canonical']??null,'robots'=>$x['meta']['_yoast_wpseo_meta-robots-noindex']??null];$item=['legacy_wp_id'=>$id,'type'=>$type,'title'=>$p->post_title,'slug'=>Str::slug($p->post_name?:$p->post_title),'status'=>$p->post_status,'legacy_url'=>'/'.ltrim($p->post_name,'/').'/', 'shortcodes'=>$v['shortcodes'],'unknown_shortcodes'=>$v['unknown'],'removed'=>$z['removed'],'seo'=>array_map(fn($q)=>$q!==null,$seo),'terms'=>collect($x['terms'])->map(fn($q)=>['id'=>$q->term_id,'taxonomy'=>$q->taxonomy,'name'=>$q->name])->all(),'anomalies'=>array_merge($v['unknown'],in_array('script',$z['removed'])?['legacy_script_removed']:[],in_array('iframe',$z['removed'])?['legacy_iframe_removed']:[])];if($this->option('apply'))DB::transaction(function()use($type,$id,$p,$z,$seo,$x){$model=$type==='post'?Article::class:Page::class;$o=$model::updateOrCreate(['legacy_wp_id'=>$id],['legacy_author_id'=>$p->post_author?:null,'original_title'=>$p->post_title,'title'=>$p->post_title,'slug'=>Str::slug($p->post_name?:$p->post_title),'content_html'=>$z['html'],'status'=>$p->post_status==='publish'?'published':$p->post_status,'legacy_url'=>'/'.ltrim($p->post_name,'/').'/', 'seo_title'=>$seo['title'],'seo_description'=>$seo['description'],'seo_canonical'=>$seo['canonical'],'seo_robots'=>$seo['robots'],'legacy_published_at'=>$p->post_date_gmt,'legacy_modified_at'=>$p->post_modified_gmt]);if($type==='post'){$cats=[];$tags=[];foreach($x['terms'] as $q){if($q->taxonomy==='category')$cats[]=EditorialCategory::updateOrCreate(['legacy_term_id'=>$q->term_id],['name'=>$q->name,'slug'=>$q->slug])->id;else $tags[]=EditorialTag::updateOrCreate(['legacy_term_id'=>$q->term_id],['name'=>$q->name,'slug'=>$q->slug])->id;}$o->categories()->sync($cats);$o->tags()->sync($tags);}if(!empty($x['meta']['_thumbnail_id']))ContentMedia::updateOrCreate(['content_type'=>$type,'content_id'=>$o->id,'legacy_attachment_id'=>(int)$x['meta']['_thumbnail_id'],'role'=>'featured'],[]);});$report['items'][]=$item;} $out=base_path($this->option('out').'-'.$type);File::put($out.'.json',json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));File::put($out.'.md','# Content migration '.ucfirst($type)."\n\n".json_encode($report,JSON_PRETTY_PRINT));$this->info($out.'.json');return 0;}}
